def next_action(state):
    if state["status"] == "completed":
        return {"kind": "finish"}
    if state["last_result"] == "uncertain":
        return {"kind": "tool_call", "name": "observe"}
    if state["subgoal"] == "locate":
        return {"kind": "tool_call", "name": "locate_handle"}
    if state["subgoal"] == "approach":
        return {"kind": "tool_call", "name": "move_to_pregrasp"}
    return {"kind": "ask_human"}

state = {"status":"running", "subgoal":"locate", "last_result":None}
assert next_action(state)["name"] == "locate_handle"
state["subgoal"] = "approach"
assert next_action(state)["name"] == "move_to_pregrasp"
print("Agent loop checks passed.")

