def update_state(state, receipt):
    out = dict(state)
    status = receipt.get("status")
    if status == "succeeded":
        out["subgoal"] = receipt.get("next_subgoal", out.get("subgoal"))
    elif status == "failed":
        out["status"] = "needs_recovery"
    elif status == "uncertain":
        out["status"] = "needs_verification"
    return out

