ALLOWED = {
    "accepted": {"running", "failed", "cancelled"},
    "running": {"yielded", "succeeded", "failed", "cancelled", "uncertain"},
    "yielded": {"running", "failed", "cancelled"},
    "succeeded": set(), "failed": set(), "cancelled": set()
}

def transition(current, nxt):
    if nxt not in ALLOWED.get(current, set()):
        raise ValueError("illegal transition")
    return nxt

assert transition("running", "yielded") == "yielded"
print("Skill lifecycle checks passed.")

