def should_promote(base, candidate, min_gain=0.05):
    gain = candidate["success"] - base["success"]
    no_regression = candidate["core"] >= base["core"]
    safe = candidate["violations"] == 0
    return gain >= min_gain and no_regression and safe

base = {"success":0.70,"core":0.92}
good = {"success":0.78,"core":0.93,"violations":0}
unsafe = {"success":0.85,"core":0.90,"violations":1}
assert should_promote(base, good)
assert not should_promote(base, unsafe)
print("skill promotion passed.")

