def summarize_runs(runs):
    if not runs:
        raise ValueError("runs cannot be empty")
    n = len(runs)
    return {
        "success_rate": sum(x["success"] for x in runs) / n,
        "intervention_rate": sum(x["intervention"] for x in runs) / n,
        "mean_duration": sum(x["duration"] for x in runs) / n,
        "safety_violations": sum(x["violations"] for x in runs)
    }

runs = [
    {"success":1,"intervention":0,"duration":20,"violations":0},
    {"success":0,"intervention":1,"duration":35,"violations":0},
    {"success":1,"intervention":0,"duration":18,"violations":0}
]
assert summarize_runs(runs)["success_rate"] == 2/3
print("evaluation aggregation passed.")

